const staticData = $getWorkflowStaticData('global');
const oldest = staticData.lastTs || (Date.now() / 1000 - 600).toFixed(6);
return [{ json: { oldest } }];

const inputItems = $input.all();
let rawMessages;
if (inputItems.length === 1 && Array.isArray(inputItems[0].json.messages)) {
  rawMessages = inputItems[0].json.messages;
} else {
  rawMessages = inputItems.map(i => i.json);
}

const staticData = $getWorkflowStaticData('global');
const lastTs = parseFloat(staticData.lastTs || '0');

const newMessages = rawMessages.filter(m => {
  if (!m || !m.ts) return false;
  if (m.bot_id || m.subtype === 'bot_message') return false;
  return parseFloat(m.ts) > lastTs;
});

if (rawMessages.length > 0) {
  const maxTs = Math.max(...rawMessages.map(m => parseFloat(m.ts || '0')));
  if (maxTs > lastTs) staticData.lastTs = String(maxTs);
}

return newMessages.map(m => ({ json: { text: m.text, ts: m.ts, user: m.user } }));

const items = $input.all();
const results = [];
const now = DateTime.now().setZone('Asia/Seoul');

for (const item of items) {
  const text = (item.json.text || '').trim();
  if (!text) continue;

  let match;

  match = text.match(/^(오늘|내일|모레)\s+(\d{1,2}):(\d{2})\s+(.+)$/);
  if (match) {
    const [, dayWord, hh, mm, content] = match;
    const offset = dayWord === '오늘' ? 0 : dayWord === '내일' ? 1 : 2;
    const baseDate = now.plus({ days: offset }).set({ hour: parseInt(hh, 10), minute: parseInt(mm, 10), second: 0, millisecond: 0 });
    results.push({ json: { title: content.trim(), startDateTime: baseDate.toISO(), durationMinutes: 60 } });
    continue;
  }

  match = text.match(/^(\d{4}-\d{2}-\d{2})\s+(\d{1,2}):(\d{2})\s+(.+)$/);
  if (match) {
    const [, dateStr, hh, mm, content] = match;
    const baseDate = DateTime.fromISO(`${dateStr}T${hh.padStart(2, '0')}:${mm}:00`, { zone: 'Asia/Seoul' });
    results.push({ json: { title: content.trim(), startDateTime: baseDate.toISO(), durationMinutes: 60 } });
    continue;
  }

  match = text.match(/^(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})\s+(.+)$/);
  if (match) {
    const [, mo, da, hh, mm, content] = match;
    const baseDate = DateTime.fromObject(
      { year: now.year, month: parseInt(mo, 10), day: parseInt(da, 10), hour: parseInt(hh, 10), minute: parseInt(mm, 10) },
      { zone: 'Asia/Seoul' }
    );
    results.push({ json: { title: content.trim(), startDateTime: baseDate.toISO(), durationMinutes: 60 } });
    continue;
  }
}

return results;
